function explainError(nodeName, message) {
  const m = (message || '').toLowerCase();
  const n = (nodeName || '').toLowerCase();
  const isX = n.startsWith('x:') || m.includes('twitter.com') || m.includes('x.com');
  const isNotion = n.includes('notion') || m.includes('notion.com');
  const isClaude = n.includes('claude') || m.includes('anthropic.com');
  const isDiscordBot = n.includes('discord') || m.includes('discord-bot');

  if (m.includes('creditsdepleted') || m.includes('does not have any credits') || m.includes('payment required') || m.includes('402')) {
    return 'X\u306e\u6295\u7a3f\u30af\u30ec\u30b8\u30c3\u30c8\u304c\u4e0d\u8db3\u3057\u3066\u3044\u307e\u3059\u3002Developer Portal\u3067\u30af\u30ec\u30b8\u30c3\u30c8\u3092\u8ffd\u52a0\u8cfc\u5165\u3057\u3066\u304f\u3060\u3055\u3044\u3002';
  }
  if (m.includes('401') || m.includes('unauthorized') || m.includes('invalid or expired token')) {
    if (isX) return 'X\u306e\u8a8d\u8a3c\u304c\u7121\u52b9\u306b\u306a\u3063\u3066\u3044\u307e\u3059\u3002\u518d\u5ea6\u30a2\u30ab\u30a6\u30f3\u30c8\u9023\u643a\uff08OAuth\u518d\u8a8d\u8a3c\uff09\u304c\u5fc5\u8981\u306a\u53ef\u80fd\u6027\u304c\u3042\u308a\u307e\u3059\u3002';
    if (isNotion) return 'Notion\u306e\u8a8d\u8a3c\u30a8\u30e9\u30fc\u3067\u3059\u3002API\u30ad\u30fc\u3092\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002';
    if (isClaude) return 'Claude API\u30ad\u30fc\u304c\u7121\u52b9\u3067\u3059\u3002';
    return '\u8a8d\u8a3c\u30a8\u30e9\u30fc\u3067\u3059\u3002\u8a72\u5f53\u30b5\u30fc\u30d3\u30b9\u306eAPI\u30ad\u30fc/\u30c8\u30fc\u30af\u30f3\u3092\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002';
  }
  if (m.includes('429') || m.includes('rate limit') || m.includes('too many requests')) {
    return 'API\u306e\u30ec\u30fc\u30c8\u5236\u9650\uff08\u9001\u4fe1\u3057\u3059\u304e\uff09\u306b\u9054\u3057\u307e\u3057\u305f\u3002\u6642\u9593\u3092\u7f6e\u3051\u3070\u81ea\u52d5\u3067\u56de\u5fa9\u3059\u308b\u53ef\u80fd\u6027\u304c\u3042\u308a\u307e\u3059\u3002';
  }
  if (m.includes('529') || m.includes('overloaded')) {
    return 'Claude API\u304c\u73fe\u5728\u6df7\u96d1\u3057\u3066\u3044\u307e\u3059\u3002\u6642\u9593\u3092\u7f6e\u3044\u3066\u81ea\u52d5\u7684\u306b\u518d\u8a66\u884c\u3055\u308c\u307e\u3059\u3002';
  }
  if (m.includes('404') || m.includes('not found')) {
    return '\u5bfe\u8c61\u306e\u30da\u30fc\u30b8\u30fb\u30c7\u30fc\u30bf\u304c\u898b\u3064\u304b\u308a\u307e\u305b\u3093\u3067\u3057\u305f\uff08\u524a\u9664\u3055\u308c\u3066\u3044\u308b\u304b\u3001ID\u304c\u8aa4\u3063\u3066\u3044\u308b\u53ef\u80fd\u6027\u304c\u3042\u308a\u307e\u3059\uff09\u3002';
  }
  if (m.includes('econnrefused') || m.includes('timeout') || m.includes('etimedout')) {
    if (isDiscordBot) return 'Discord bot\uff08\u30b3\u30f3\u30c6\u30ca\uff09\u306b\u63a5\u7d9a\u3067\u304d\u307e\u305b\u3093\u3067\u3057\u305f\u3002bot\u304c\u8d77\u52d5\u3057\u3066\u3044\u308b\u304b\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002';
    return '\u30b5\u30fc\u30d3\u30b9\u3078\u306e\u63a5\u7d9a\u304c\u30bf\u30a4\u30e0\u30a2\u30a6\u30c8\u3001\u307e\u305f\u306f\u62d2\u5426\u3055\u308c\u307e\u3057\u305f\u3002';
  }
  if (m.includes('400') || m.includes('bad request') || m.includes('validation')) {
    return '\u9001\u4fe1\u5185\u5bb9\u306b\u8aa4\u308a\u304c\u3042\u308a\u307e\u3059\uff08\u6587\u5b57\u6570\u8d85\u904e\u3084\u5fc5\u9808\u9805\u76ee\u306e\u4e0d\u8db3\u306a\u3069\u304c\u8003\u3048\u3089\u308c\u307e\u3059\uff09\u3002';
  }
  if (m.includes('500') || m.includes('internal server error')) {
    return '\u63a5\u7d9a\u5148\u30b5\u30fc\u30d3\u30b9\u5074\u3067\u4e00\u6642\u7684\u306a\u554f\u984c\u304c\u767a\u751f\u3057\u3066\u3044\u307e\u3059\u3002';
  }
  return '\u539f\u56e0\u4e0d\u660e\u306e\u30a8\u30e9\u30fc\u3067\u3059\u3002\u4e0b\u8a18\u306e\u8a73\u7d30\u30e1\u30c3\u30bb\u30fc\u30b8\u3092\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002';
}

const item = $input.first().json;
const wf = item.workflow ?? {};
const exec = item.execution ?? {};
const err = exec.error ?? {};
const nodeName = exec.lastNodeExecuted ?? '';
const rawMessage = err.message ?? '(\u30e1\u30c3\u30bb\u30fc\u30b8\u306a\u3057)';

const MAX_LEN = 500;
const truncatedRaw = rawMessage.length > MAX_LEN ? rawMessage.slice(0, MAX_LEN) + '...(\u4ee5\u4e0b\u7701\u7565)' : rawMessage;

const title = `\u26a0\ufe0f \u30ef\u30fc\u30af\u30d5\u30ed\u30fc\u30a8\u30e9\u30fc: ${wf.name ?? '(\u4e0d\u660e)'}`;
const lines = [
  explainError(nodeName, rawMessage),
  '',
  `\u5931\u6557\u3057\u305f\u30ce\u30fc\u30c9: ${nodeName || '(\u4e0d\u660e)'}`,
  `\u8a73\u7d30: ${truncatedRaw}`,
];
if (exec.url) lines.push(`\u5b9f\u884c\u8a73\u7d30: ${exec.url}`);

return [{
  json: {
    title,
    message: lines.join('\n')
  }
}];
